-- Seeds public.packages from lib/data/packages.ts (generated; Buy 1 Get 1 excluded — deleted in production).
-- Run in Supabase Dashboard -> SQL Editor. Works on an empty project (creates the table if missing).
-- Safe to re-run: existing slugs are updated.

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Same definition as full_setup.sql / schema.sql
CREATE TABLE IF NOT EXISTS public.packages (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  short_description TEXT NOT NULL,
  description TEXT NOT NULL,
  price NUMERIC(10, 2) NOT NULL,
  duration TEXT NOT NULL,
  featured BOOLEAN DEFAULT false,
  active BOOLEAN DEFAULT true,
  main_image TEXT NOT NULL,
  gallery TEXT[] DEFAULT '{}',
  pickup_info TEXT DEFAULT 'Pickups available across all major Dubai hotels and apartments.',
  cancellation_policy TEXT DEFAULT 'Free cancellation up to 24 hours prior to departure.',
  seo_title TEXT,
  seo_description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Public site reads active packages with the anon key (matches security_hardening.sql)
ALTER TABLE public.packages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public read packages" ON public.packages;
CREATE POLICY "Public read packages" ON public.packages FOR SELECT TO anon USING (active = true);
CREATE INDEX IF NOT EXISTS idx_packages_active_slug ON public.packages (active, slug);
CREATE INDEX IF NOT EXISTS idx_packages_featured ON public.packages (featured) WHERE active = true;

INSERT INTO public.packages
  (name, slug, short_description, description, price, duration, featured, active, main_image, gallery, pickup_info, cancellation_policy, seo_title, seo_description)
VALUES
  ('Evening Desert Safari Dubai', 'evening-desert-safari', 'Dubai''s classic evening desert adventure with 4x4 red dune bashing, camel riding, sunset views, international BBQ dinner buffet, and thrilling live entertainment.', 'The quintessential Dubai desert safari. Pick up directly from your doorstep and journey into the crimson Lahbab dunes. Experience exhilarating dune bashing with expert drivers, ride camels across pristine sands, try sandboarding, and unwind at our atmospheric desert camp with live belly dancing, fire shows, Tanoura dance, and an expansive BBQ dinner buffet.', 89, '6 - 7 Hours', true, true, '/images/tours/evening-desert-safari-dubai.webp', ARRAY['/images/tours/buy-1-get-1-free-safari.webp', '/images/tours/vip-evening-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all hotels and residences across Dubai.', 'Free cancellation up to 24 hours prior to safari departure.', 'Evening Desert Safari Dubai with BBQ Dinner & Shows', 'Book the top evening desert safari in Dubai. Red dune bashing in 4x4 Land Cruiser, camel ride, BBQ buffet, belly dancing, and fire show.'),
  ('VIP Desert Safari Dubai', 'vip-desert-safari', 'Indulge in royal treatment with VIP sofa seating, dedicated waiter table service, premium VIP BBQ buffet, 4x4 dune bashing, camel ride, and front-row stage shows.', 'Elevate your desert experience with luxury VIP treatment. Skip the buffet queues with dedicated waiter service delivering hot gourmet BBQ and Arabic dishes directly to your cushioned VIP sofa table with front-row views of the center stage. Includes high-red dune bashing in a 4x4 Land Cruiser, camel riding, sandboarding, and all traditional camp amenities.', 150, '6 - 7 Hours', true, true, '/images/tours/vip-evening-desert-safari-dubai.webp', ARRAY['/images/tours/vip-desert-safari-dubai-with-quad-bike.webp', '/images/tours/vip-private-evening-desert-safari.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all hotels and apartments across Dubai.', 'Free cancellation up to 24 hours prior to departure.', 'VIP Desert Safari Dubai | Table Waiter Service & Sofa Seating', 'Experience VIP Desert Safari in Dubai with dedicated sofa table waiter service, gourmet BBQ dinner, 4x4 dune bashing, camel ride, and live shows.'),
  ('Evening Desert Safari with ATV Quad Bike Ride', 'evening-desert-safari-with-atv-quad-bike-ride', 'The ultimate adventure combo! Enjoy 30 minutes of self-drive ATV Quad Biking in the open desert, followed by 4x4 dune bashing, camel ride, BBQ dinner, and live shows.', 'Combine high-octane self-drive quad biking with Dubai''s complete evening desert safari. Take control of a powerful all-terrain quad bike for 30-45 minutes on dedicated desert circuits and open dunes with expert supervision and full safety gear. Afterward, experience heart-racing 4x4 Land Cruiser dune bashing, sandboarding, camel rides, and an evening of dinner and entertainment at the camp.', 250, '6 - 7 Hours', true, true, '/images/tours/evening-desert-safari-with-quad-bike.webp', ARRAY['/images/tours/atv-quad-bike-ride-dubai-1-person.webp', '/images/tours/vip-desert-safari-dubai-with-quad-bike.webp', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Complimentary hotel pickup & drop-off across Dubai.', 'Free cancellation up to 24 hours before tour start.', 'Evening Desert Safari with ATV Quad Bike Ride Dubai', 'Book Evening Desert Safari with ATV Quad Bike ride in Dubai. 30 mins self-drive quad bike, 4x4 dune bashing, BBQ dinner, and live shows.'),
  ('VIP Evening Desert Safari Dubai with ATV Quad Bike Ride', 'vip-evening-desert-safari-dubai-with-atv-quad-bike-ride', 'The ultimate VIP adrenaline safari! Includes 30-45 minutes self-drive ATV Quad Biking, 4x4 red dune bashing, VIP sofa seating, and dedicated waiter table service with BBQ dinner.', 'Enjoy supreme comfort coupled with pure adrenaline. Start with a thrilling 30-45 minute self-drive quad bike adventure over shifting desert terrain, followed by expert 4x4 dune bashing and sandboarding. At the camp, relax in your reserved VIP sofa section with dedicated waiter service catering directly to your table while you enjoy 7 live performances and a lavish VIP BBQ buffet.', 300, '6 - 7 Hours', false, true, '/images/tours/vip-desert-safari-dubai-with-quad-bike.webp', ARRAY['/images/tours/vip-evening-desert-safari-dubai.webp', '/images/tours/atv-quad-bike-ride-dubai-1-person.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all hotels in Dubai.', 'Free cancellation up to 24 hours prior to departure.', 'VIP Desert Safari with ATV Quad Bike Ride Dubai', 'Indulge in VIP Desert Safari with ATV Quad Bike in Dubai. VIP sofa seating, waiter table service, 30 min quad bike, 4x4 dune bashing, BBQ dinner.'),
  ('Private Evening Desert Safari Dubai', 'private-evening-desert-safari-dubai', 'An exclusive private 4x4 Land Cruiser reserved entirely for your family or group of up to 7 persons. Includes private dune bashing, sunset stop, camp BBQ dinner, and shows.', 'Enjoy complete privacy and personalized pace with a private 4x4 Land Cruiser dedicated exclusively to your family or friends (up to 7 guests). Your private licensed safari marshal will pick you up directly from your doorstep, tailor dune bashing intensity to your comfort, and guide you through an enchanting evening of desert activities, camel rides, BBQ dinner, and live shows.', 650, '6 - 7 Hours', false, true, '/images/tours/private-evening-desert-safari-dubai.webp', ARRAY['/images/tours/vip-private-evening-desert-safari.webp', '/images/tours/evening-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Private pickup from any hotel or residence in Dubai.', 'Free cancellation up to 24 hours prior to departure.', 'Private Evening Desert Safari Dubai | Exclusive 4x4 Jeep', 'Book a Private Evening Desert Safari in Dubai for up to 7 guests. Exclusive 4x4 Land Cruiser, customized dune bashing, camel rides, BBQ dinner.'),
  ('VIP Private Desert Safari Dubai', 'vip-private-desert-safari-dubai', 'The gold standard of desert luxury. Private 4x4 Land Cruiser for up to 7 guests, VIP sofa table seating at the camp, dedicated waiter service, and gourmet BBQ dining.', 'The premier luxury desert package. You receive a dedicated private 4x4 Land Cruiser for your party, customized dune bashing across Dubai''s iconic red dunes, plus reserved VIP sofa seating at the desert camp with personal waiter service delivering exquisite multi-course BBQ dishes directly to your table while enjoying spectacular live entertainment.', 850, '6 - 7 Hours', true, true, '/images/tours/vip-private-evening-desert-safari.webp', ARRAY['/images/tours/vip-evening-desert-safari-dubai.webp', '/images/tours/private-evening-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available across Dubai, Sharjah, and Ajman.', 'Free cancellation up to 24 hours before tour start.', 'VIP Private Desert Safari Dubai | Private Jeep & Waiter Service', 'Book VIP Private Desert Safari in Dubai for up to 7 people. Private 4x4 Land Cruiser, VIP sofa seating, table waiter service, BBQ dinner, and shows.'),
  ('Morning Desert Safari Dubai', 'morning-desert-safari', 'Experience the cool serenity of the Arabian desert at dawn. Includes early morning pickup, 4x4 dune bashing, sunrise photography, camel trekking, and sandboarding.', 'Ideal for travelers with tight afternoon schedules or early risers who want to experience the tranquil beauty of the desert in cool morning temperatures. Witness the sun rising over pristine red dunes, feel the thrill of 4x4 dune bashing, surf silky dunes on a sandboard, and enjoy gentle camel rides before returning to the city by midday.', 199, '4 - 5 Hours', false, true, '/images/tours/morning-desert-safari-dubai.webp', ARRAY['/images/tours/private-morning-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all hotels in Dubai.', 'Free cancellation up to 24 hours prior to departure.', 'Morning Desert Safari Dubai | Sunrise Dune Bashing & Camel Ride', 'Book Morning Desert Safari in Dubai. 05:00 AM pickup, 4x4 red dune bashing, sunrise photography, camel rides, sandboarding, and hotel transfers.'),
  ('Private Morning Desert Safari Dubai', 'private-morning-desert-safari-dubai', 'Private 4x4 Land Cruiser exclusively for your family or friends at dawn. Early 05:00 AM pickup, private sunrise dune bashing, camel rides, and sandboarding.', 'Enjoy peaceful desert sunrises with your own private vehicle and safari marshal. Perfect for photographers, families with young children, or couples seeking privacy. Experience high-octane red dune bashing, camel trekking, sandboarding, and sunrise photography at your own pace.', 699, '4 - 5 Hours', false, true, '/images/tours/private-morning-desert-safari-dubai.webp', ARRAY['/images/tours/morning-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from any Dubai location.', 'Free cancellation up to 24 hours prior to departure.', 'Private Morning Desert Safari Dubai | Exclusive Sunrise 4x4 Jeep', 'Book Private Morning Desert Safari in Dubai for up to 7 guests. Exclusive 4x4 Land Cruiser, 05:00 AM pickup, sunrise dune bashing, and camel rides.'),
  ('Half Day Desert Safari Dubai', 'halfday-desert-safari-dubai', 'A fast, high-impact desert adventure in a private 4x4 Land Cruiser. Features intense dune bashing, daylight camel rides, sandboarding, and winter bonfire.', 'Designed for travelers on a schedule who want the pure desert driving thrill without camp shows. A dedicated private 4x4 Land Cruiser takes you into the open dunes for thrilling roller-coaster dune bashing, sandboarding, camel rides, and mineral water refreshments before returning directly to the city.', 549, '4 Hours', false, true, '/images/tours/half-day-desert-safari-dubai.webp', ARRAY['/images/tours/evening-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Available for all hotels and residences in Dubai.', 'Free cancellation up to 24 hours prior to departure.', 'Half Day Desert Safari Dubai | Private 4x4 Land Cruiser', 'Book Half Day Desert Safari in Dubai. Private 4x4 Land Cruiser, dune bashing, daylight camel riding, sandboarding, and hotel pickup.'),
  ('Overnight Desert Safari Dubai', 'overnight-desert-safari', 'The complete 24-hour desert experience! Full evening safari with BBQ dinner & 7 live shows, overnight stay in Bedouin tents under the starry sky, midnight bonfire, and sunrise VIP breakfast.', 'Immerse yourself completely in the magic of the Arabian desert. After enjoying the full evening desert safari with dune bashing, camel rides, grand BBQ dinner, and 7 live stage shows, stay overnight at our secure Bedouin desert camp. Sleep in comfortable carpeted tents equipped with mattresses, pillows, and warm blankets. Enjoy a midnight campfire under the star-studded canopy, wake up to a quiet desert sunrise, and savor a freshly prepared VIP breakfast before returning to Dubai at 07:00 AM.', 350, '17 - 18 Hours (Overnight)', true, true, '/images/tours/over-night-desert-safari-dubai.webp', ARRAY['/images/tours/evening-desert-safari-dubai.webp', '/images/tours/vip-evening-desert-safari-dubai.webp', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all Dubai hotels and residences.', 'Free cancellation up to 24 hours prior to departure.', 'Overnight Desert Safari Dubai | Bedouin Camp & Breakfast', 'Book Overnight Desert Safari in Dubai at AED 350. Includes 4x4 dune bashing, BBQ dinner, 7 live shows, overnight tent stay, campfire, and sunrise VIP breakfast.'),
  ('ATV Quad Bike Self Drive 1 Person', 'atv-quad-bike-self-drive-1-person', 'Take command of a powerful automatic ATV quad bike across open desert sand dunes. 30-45 minutes of pure self-drive excitement with safety gear and expert guides.', 'Feel the rush of adrenaline as you pilot a 250cc-400cc automatic ATV quad bike over natural sand hills and desert tracks. No prior riding experience or driving license is required. Our professional guides provide full safety briefing, helmets, and protective goggles to ensure a fun, safe, and exhilarating self-drive ride.', 149, '1 - 2 Hours', false, true, '/images/tours/atv-quad-bike-ride-dubai-1-person.webp', ARRAY['/images/tours/atv-quad-bike-ride-dubai-2-persons.webp', '/images/tours/evening-desert-safari-with-quad-bike.webp', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Self-arrival at desert track or optional hotel transfer add-on.', 'Free cancellation up to 24 hours before tour start.', 'ATV Quad Bike Self Drive Dubai (1 Person) | AED 149', 'Ride an ATV quad bike in Dubai desert from AED 149. 30-45 minutes self-drive, safety helmet and goggles, expert instructor, and sandboarding.'),
  ('ATV Quad Bike Self Drive 2 Person', 'atv-quad-bike-self-drive-2-persons', 'Double the fun! Share a high-torque 2-seater quad bike with a friend or partner across scenic Dubai desert tracks. 30-45 minutes self-drive with guide and gear.', 'Designed for couples or friends who want to share the adventure together on one high-performance double quad bike. Navigate the desert terrain together under the supervision of experienced guides with full safety gear and helmets provided.', 249, '1 - 2 Hours', false, true, '/images/tours/atv-quad-bike-ride-dubai-2-persons.webp', ARRAY['/images/tours/atv-quad-bike-ride-dubai-1-person.webp', '/images/tours/evening-desert-safari-with-quad-bike.webp', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Desert track location with available hotel transfer option.', 'Free cancellation up to 24 hours prior to departure.', 'ATV Quad Bike Self Drive 2 Persons Dubai | AED 249', 'Book 2-person double ATV quad bike self-drive in Dubai desert for AED 249. 30-45 minutes, safety gear for both riders, expert guide.'),
  ('01 Seater Dune Buggy RZR-1000CC Self Drive', '01-seater-dune-buggy-rzr-1000cc-self-drive', 'Take the wheel of an authentic 1000cc Polaris RZR Dune Buggy! 45 minutes of intense solo dune driving with roll cage, safety harness, and sandboarding.', 'Experience the pinnacle of desert motorsport. Drive an aggressive single-seater Polaris RZR 1000cc off-road buggy engineered to conquer towering red sand dunes. Equipped with full competition roll cage, 4-point safety harness, race suspension, and automatic transmission. Led by a pace guide to ensure maximum fun and total safety.', 599, '2 - 3 Hours', false, true, '/images/tours/rzr-1000cc-1-seater-buggy.webp', ARRAY['/images/tours/2-seater-buggy.webp', '/images/tours/rzr-1000cc-2-seater-buggy.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available on request or meet directly at the buggy desert base.', 'Free cancellation up to 24 hours prior to departure.', '1 Seater Dune Buggy Polaris RZR 1000cc Dubai | AED 599', 'Drive a 1-seater Polaris RZR 1000cc dune buggy in Dubai desert. 45 minutes self-drive, full roll cage, safety harness, and sandboarding.'),
  ('02 Seater Dune Buggy RZR-1000CC Self Drive', '02-seater-dune-buggy-rzr-1000cc-self-drive', 'Share the ultimate off-road adrenaline in a 2-seater Polaris RZR 1000cc Buggy. 45 minutes of extreme dune driving across Dubai''s deepest red sands.', 'Dubai''s most popular dune buggy experience for couples and pairs of friends. Pilot a championship-proven 2-seater Polaris RZR 1000cc with automatic transmission, race-tuned long-travel suspension, and high-strength roll cage. Swap drivers halfway through if desired, and capture stunning desert action photos.', 749, '2 - 3 Hours', true, true, '/images/tours/2-seater-buggy.webp', ARRAY['/images/tours/rzr-1000cc-1-seater-buggy.webp', '/images/tours/rzr-1000cc-2-seater-buggy.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Transfers available across Dubai upon request.', 'Free cancellation up to 24 hours prior to departure.', '2 Seater Dune Buggy Polaris RZR 1000cc Dubai | AED 749', 'Book 2-seater Polaris RZR 1000cc dune buggy self drive in Dubai at AED 749. 45 mins ride, roll cage, sandboarding, and guide included.'),
  ('04 Seater Dune Buggy RZR-1000CC Self Drive', '04-seater-dune-buggy-rzr-1000cc-self-drive', 'Bring the whole family or friend group! 4-Seater Polaris RZR 1000cc Buggy self-drive for 45 minutes across Dubai''s massive red dunes.', 'The premier off-road thrill for families and groups of friends. Seat up to 4 passengers comfortably in bucket seats with multi-point harnesses and full overhead roll protection. Power across untouched desert dunes with 1000cc performance under the guidance of our professional desert marshals.', 899, '2 - 3 Hours', false, true, '/images/tours/rzr-1000cc-2-seater-buggy.webp', ARRAY['/images/tours/2-seater-buggy.webp', '/images/tours/can-am-3x-marvick-4-seater-buggy.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Hotel pickup available on request.', 'Free cancellation up to 24 hours prior to departure.', '4 Seater Dune Buggy Polaris RZR 1000cc Dubai | AED 899', 'Book 4-seater Polaris RZR 1000cc dune buggy in Dubai for family and friends. 45 mins self-drive, roll cage, sandboarding, AED 899.'),
  ('02 Seater Can-am 3x-Marvick Buggy Self Drive', '02-seater-can-am-3x-marvick-buggy-self-drive', 'Unleash 195 horsepower with the legendary Can-Am Maverick X3 Turbo! 45 minutes of extreme high-speed desert mastery with unmatched suspension travel.', 'The ultimate supercar of the sand dunes. The Can-Am Maverick X3 Turbo delivers breathtaking acceleration, incredible Fox racing shocks suspension, and unstoppable power across Dubai''s tallest red dunes. For adrenaline junkies who want nothing less than the absolute fastest, most capable dune buggy in existence.', 999, '2 - 3 Hours', true, true, '/images/tours/can-am-3x-marvick-2-seater-buggy.webp', ARRAY['/images/tours/can-am-3x-marvick-4-seater-buggy.webp', '/images/tours/2-seater-buggy.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Transfers available across all Dubai hotels.', 'Free cancellation up to 24 hours prior to departure.', '2 Seater Can-Am Maverick X3 Turbo Buggy Dubai | AED 999', 'Drive the 195HP Can-Am Maverick X3 Turbo buggy in Dubai desert. 45 minutes of extreme self-drive horsepower, sandboarding, and guide.'),
  ('04 Seater Can-am 3x-Marvick Buggy Self Drive', '04-seater-can-am-3x-marvick-buggy-self-drive', 'The undisputed king of 4-seater off-road buggies! Drive the Can-Am Maverick X3 Turbo with 4 passengers for 45 minutes across Dubai''s grandest red dunes.', 'Share the ultimate off-road rush with 4 guests in the monstrous Can-Am Maverick X3 Turbo Max. Boasting extreme horsepower, industry-leading suspension travel, and aerospace-grade chassis strength, it effortlessly glides across razor-sharp dune crests and steep sand drops in supreme safety and comfort.', 1499, '2 - 3 Hours', false, true, '/images/tours/can-am-3x-marvick-4-seater-buggy.webp', ARRAY['/images/tours/can-am-3x-marvick-2-seater-buggy.webp', '/images/tours/rzr-1000cc-2-seater-buggy.webp', 'https://images.unsplash.com/photo-1547234935-80c7145ec969?q=80&w=1000&auto=format&fit=crop']::TEXT[], 'Pickups available from all hotels across Dubai.', 'Free cancellation up to 24 hours prior to departure.', '4 Seater Can-Am Maverick X3 Turbo Buggy Dubai | AED 1499', 'Book 4-seater Can-Am Maverick X3 Turbo Dune Buggy in Dubai. Extreme 45-minute family/group self drive, sandboarding, guide.')
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
  price = EXCLUDED.price,
  duration = EXCLUDED.duration,
  featured = EXCLUDED.featured,
  active = EXCLUDED.active,
  main_image = EXCLUDED.main_image,
  gallery = EXCLUDED.gallery,
  pickup_info = EXCLUDED.pickup_info,
  cancellation_policy = EXCLUDED.cancellation_policy,
  seo_title = EXCLUDED.seo_title,
  seo_description = EXCLUDED.seo_description,
  updated_at = NOW();
